SELECT subalarm.total_num, subalarm.un_confirmed_num, subalarm.progress_confirmed_num, subalarm.suspend_num , subalarm.handler_num , subalarm.actual_num , subalarm.impractical_num , subalarm.timeout_num , subalarm.market_tenant , subalarm.processing_time, mc.market_name FROM market_config mc INNER JOIN ( SELECT COUNT( 1 ) AS total_num, COALESCE ( SUM( IF ( ar.alarm_status = 'ALARM_UN_CONFIRMED', 1, 0 )), 0 ) AS un_confirmed_num, COALESCE ( SUM( IF ( ar.alarm_status = 'ALARM_PROGRESS_CONFIRMED', 1, 0 )), 0 ) AS progress_confirmed_num, COALESCE ( SUM( IF ( ar.alarm_status = 'ALARM_SUSPEND', 1, 0 )), 0 ) AS suspend_num, COALESCE ( SUM( IF ( ar.alarm_status = 'ALARM_HANDLER', 1, 0 )), 0 ) AS handler_num, COALESCE ( SUM( IF ( ar.alarm_handler_result = 'ALARM_ACTUAL', 1, 0 )), 0 ) AS actual_num, COALESCE ( SUM( IF ( ar.alarm_handler_result = 'ALARM_IMPRACTICAL', 1, 0 )), 0 ) AS impractical_num, COALESCE ( SUM( IF ( ar.alarm_status != 'ALARM_HANDLER' AND ar.timeout_process_time <= NOW() OR ar.alarm_status = 'ALARM_HANDLER' AND timeout_process_time <= ar.alarm_handler_time, 1, 0 )), 0 ) AS timeout_num, COALESCE (SUM(ar.processing_time),0) as processing_time, ar.market_tenant FROM safety_alarm_record ar
ar.displayed = true
and ( ar.alarm_event_name like concat('%',#{query.keyword},'%') or ar.alarm_target_name like concat('%',#{query.keyword},'%') )
and ar.market_tenant = #{query.marketTenant}
and ar.alarm_level_id = #{query.alarmLevelId}
and ar.alarm_type_code = #{query.alarmTypeCode}
and ar.alarm_handler_result = #{query.alarmHandlerResult}
and ar.application_code = #{query.applicationCode}
and ar.alarm_time >= #{query.period.begin}
and ar.alarm_time <= #{query.period.end}
GROUP BY ar.market_tenant ) subalarm on mc.market_tenant = subalarm.market_tenant where mc.status = true

SELECT subalarm.total_num, subalarm.un_confirmed_num, subalarm.progress_confirmed_num, subalarm.suspend_num , subalarm.handler_num , subalarm.actual_num , subalarm.impractical_num , subalarm.timeout_num , subalarm.market_tenant , subalarm.processing_time, mc.market_name FROM market_config mc INNER JOIN ( SELECT COUNT( 1 ) AS total_num, COALESCE ( SUM( IF ( ar.alarm_status = 'ALARM_UN_CONFIRMED', 1, 0 )), 0 ) AS un_confirmed_num, COALESCE ( SUM( IF ( ar.alarm_status = 'ALARM_PROGRESS_CONFIRMED', 1, 0 )), 0 ) AS progress_confirmed_num, COALESCE ( SUM( IF ( ar.alarm_status = 'ALARM_SUSPEND', 1, 0 )), 0 ) AS suspend_num, COALESCE ( SUM( IF ( ar.alarm_status = 'ALARM_HANDLER', 1, 0 )), 0 ) AS handler_num, COALESCE ( SUM( IF ( ar.alarm_handler_result = 'ALARM_ACTUAL', 1, 0 )), 0 ) AS actual_num, COALESCE ( SUM( IF ( ar.alarm_handler_result = 'ALARM_IMPRACTICAL', 1, 0 )), 0 ) AS impractical_num, COALESCE ( SUM( IF ( ar.alarm_status != 'ALARM_HANDLER' AND ar.timeout_process_time <= NOW() OR ar.alarm_status = 'ALARM_HANDLER' AND timeout_process_time <= ar.alarm_handler_time, 1, 0 )), 0 ) AS timeout_num, COALESCE (SUM(ar.processing_time),0) as processing_time, ar.market_tenant FROM safety_alarm_record ar
ar.displayed = true
and ( ar.alarm_event_name like concat('%',#{query.keyword},'%') or ar.alarm_target_name like concat('%',#{query.keyword},'%') )
and ar.market_tenant = #{query.marketTenant}
