SELECT COUNT( ar.id ) AS total_num, COALESCE ( SUM( IF ( ar.alarm_status = 'ALARM_UN_CONFIRMED', 1, 0 )), 0 ) AS un_confirmed_num, COALESCE ( SUM( IF ( ar.alarm_status = 'ALARM_PROGRESS_CONFIRMED', 1, 0 )), 0 ) AS progress_confirmed_num, COALESCE ( SUM( IF ( ar.alarm_status = 'ALARM_HANDLER', 1, 0 )), 0 ) AS handler_num, COALESCE ( SUM( IF ( ar.alarm_status != 'ALARM_UN_CONFIRMED', 1, 0 )), 0 ) AS confirmed_num, COALESCE ( SUM( IF ( ar.alarm_handler_result = 'ALARM_ACTUAL', 1, 0 )), 0 ) AS actual_num, COALESCE ( SUM( IF ( ar.alarm_status != 'ALARM_HANDLER' AND ar.timeout_process_time <= NOW(),1,0)), 0 ) AS timeout_not_handler_num, COALESCE ( SUM( IF ( ar.alarm_status != 'ALARM_HANDLER',1,0)), 0 ) AS not_handler_num, COALESCE ( SUM( IF ( ar.timeout_process_time <= NOW(),1,0)), 0 ) AS timeout_num FROM safety_alarm_record ar left join market_config mc on mc.market_tenant = ar.market_tenant
