SELECT mc.market_tenant, COALESCE(subalarm.total_num,0) as total_num, mc.market_name FROM market_config mc LEFT JOIN ( SELECT market_tenant, COUNT(id) as total_num FROM safety_alarm_record
displayed = true and alarm_status = 'ALARM_UN_CONFIRMED'
and market_tenant = #{query.marketTenant}
and alarm_type_code = #{query.alarmTypeCode}
and alarm_time >= #{query.period.begin}
and alarm_time <= #{query.period.end}
and application_code = #{query.applicationCode}
GROUP BY market_tenant ) subalarm on mc.market_tenant = subalarm.market_tenant where mc.status = true ORDER BY subalarm.total_num desc

SELECT
DATE_FORMAT(t1.alarm_time,#{query.dateExp}) as period,
COUNT(t1.id) as total_num
FROM
safety_alarm_record t1
left join market_config mc on mc.market_tenant = t1.market_tenant

    t1.displayed = true
    and mc.status = true

        and t1.market_tenant = #{query.marketTenant}


        and t1.market_tenant in

            #{marketTenant}



        and t1.alarm_status = #{query.status}


        and t1.alarm_time >= #{query.period.begin}


        and t1.alarm_time <= #{query.period.end}


        and t1.application_code = #{query.applicationCode}


GROUP BY DATE_FORMAT(t1.alarm_time,#{query.dateExp})

SELECT subalarm.`status`, subalarm.status_name, mc.market_tenant, subalarm.total_num, mc.market_name FROM market_config mc LEFT JOIN ( SELECT alarm_status as `status`, alarm_status_name as status_name, market_tenant, COUNT(id) as total_num FROM safety_alarm_record
displayed = true
and market_tenant = #{query.marketTenant}
and alarm_type_code = #{query.alarmTypeCode}
and alarm_time >= #{query.period.begin}
and alarm_time <= #{query.period.end}
and application_code = #{query.applicationCode}
GROUP BY alarm_status,alarm_status_name,market_tenant ) subalarm on mc.market_tenant = subalarm.market_tenant where mc.status = true

SELECT
COUNT( 1 ) AS total_num,
COALESCE ( SUM( IF (ar.alarm_status = 'ALARM_HANDLER', 1, 0 )), 0 ) AS handler_num,
COALESCE ( SUM( IF (ar.alarm_status != 'ALARM_UN_CONFIRMED', 1, 0 )), 0 ) AS confirmed_num,
COALESCE ( SUM( IF (ar.alarm_handler_result = 'ALARM_ACTUAL', 1, 0 )), 0 ) AS actual_num,
COALESCE (
SUM(
IF
( ar.alarm_status != 'ALARM_HANDLER' AND ar.timeout_process_time <= NOW() OR ar.alarm_status = 'ALARM_HANDLER' AND
ar.timeout_process_time <= ar.alarm_handler_time, 1, 0 )),
0
) AS timeout_num
FROM
safety_alarm_record ar
left join market_config mc on mc.market_tenant = ar.market_tenant

    ar.displayed = true
    and mc.status = true

        and ar.market_tenant = #{query.marketTenant}


        and ar.alarm_type_code = #{query.alarmTypeCode}


        and ar.alarm_time >= #{query.period.begin}


        and ar.alarm_time <= #{query.period.end}


        and ar.application_code = #{query.applicationCode}


        and ar.alarm_event_type_code = #{query.alarmEventTypeCode}

SELECT mc.market_tenant, COALESCE(subalarm.total_num,0) as total_num, mc.market_name FROM market_config mc LEFT JOIN ( SELECT market_tenant as market_tenant, market_name, COUNT(1) as total_num FROM safety_alarm_record
displayed = true
and alarm_status = 'ALARM_HANDLER'
and alarm_status != 'ALARM_UN_CONFIRMED'
and alarm_status != 'ALARM_HANDLER'
and (( alarm_status != 'ALARM_HANDLER' and timeout_process_time <= now()) or (alarm_status = 'ALARM_HANDLER' AND timeout_process_time <= alarm_handler_time))
and market_tenant = #{query.marketTenant}
and alarm_type_code = #{query.alarmTypeCode}
and alarm_time >= #{query.period.begin}
and alarm_time <= #{query.period.end}
and application_code = #{query.applicationCode}
and alarm_event_type_code = #{query.alarmEventTypeCode}
GROUP BY market_tenant ) subalarm ON mc.market_tenant = subalarm.market_tenant where mc.status = true ORDER BY subalarm.total_num DESC

